parameters.subject:
={{ [
  $json.broker,
  $json.medewerker,
  $json.vacatureTitel
].filter(v => v && String(v).trim() !== '').join(' - ') }}

parameters.bodyContent:
={{ (() => {
  const d = $json;

  const hasValue = (value) => {
    if (value === null || value === undefined) return false;

    if (Array.isArray(value)) {
      return value.some(item => hasValue(item));
    }

    return String(value).trim() !== '';
  };

  const escapeHtml = (value) => String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');

  const formatPlainText = (value) => escapeHtml(value)
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/\n/g, '<br>');

  const row = (label, value) => {
    if (!hasValue(value)) return '';

    const displayedValue = Array.isArray(value)
      ? value.filter(hasValue).join(', ')
      : value;

    return `
      <div style='margin-bottom:6px;'>
        <strong>${escapeHtml(label)}:</strong>
        ${formatPlainText(displayedValue)}
      </div>
    `;
  };

  const keywords = Array.isArray(d.gevondenKeywords)
    ? d.gevondenKeywords.filter(hasValue)
    : [];

  const matchSection = `
    <div style='
      margin-top:18px;
      padding:14px;
      border:1px solid #d9d9d9;
      background-color:#f7f7f7;
    '>
      <div style='font-weight:bold; margin-bottom:10px;'>
        MATCH
      </div>

      ${row('Medewerker', d.medewerker)}
      ${row('Score', hasValue(d.score) ? `${d.score}/10` : '')}
    </div>
  `;

  const keywordsSection = keywords.length > 0
    ? `
      <div style='
        margin-top:22px;
        border-top:1px solid #d9d9d9;
        padding-top:14px;
      '>
        <div style='font-weight:bold; margin-bottom:10px;'>
          GEVONDEN KEYWORDS
        </div>

        <ul style='margin:0; padding-left:22px; line-height:1.5;'>
          ${keywords
            .map(keyword => `
              <li style='margin-bottom:5px;'>
                ${escapeHtml(keyword)}
              </li>
            `)
            .join('')}
        </ul>
      </div>
    `
    : '';

  const assessmentSection = hasValue(d.reden)
    ? `
      <div style='
        margin-top:22px;
        border-top:1px solid #d9d9d9;
        padding-top:14px;
      '>
        <div style='font-weight:bold; margin-bottom:10px;'>
          BEOORDELING
        </div>

        <div style='line-height:1.5;'>
          ${formatPlainText(d.reden)}
        </div>
      </div>
    `
    : '';

  const vacancyContent = hasValue(d.vacatureHtml)
    ? d.vacatureHtml
    : `
      <div style='
        white-space:normal;
        overflow-wrap:anywhere;
        line-height:1.6;
      '>
        ${formatPlainText(d.vacatureTekst)}
      </div>
    `;

  const vacancySection =
    hasValue(d.vacatureHtml) || hasValue(d.vacatureTekst)
      ? `
        <div style='
          margin-top:22px;
          border-top:1px solid #d9d9d9;
          padding-top:14px;
        '>
          <div style='font-weight:bold; margin-bottom:14px;'>
            VOLLEDIGE VACATURE
          </div>

          <div style='
            font-family:Arial, Helvetica, sans-serif;
            font-size:14px;
            line-height:1.55;
            color:#222222;
            overflow-wrap:anywhere;
          '>
            ${vacancyContent}
          </div>
        </div>
      `
      : '';

  const urlSection = hasValue(d.vacatureUrl)
    ? `
      <div style='
        margin-top:22px;
        border-top:1px solid #d9d9d9;
        padding-top:14px;
      '>
        <div style='font-weight:bold; margin-bottom:8px;'>
          ORIGINELE VACATURE
        </div>

        <a
          href='${escapeHtml(d.vacatureUrl)}'
          target='_blank'
          style='color:#800080; text-decoration:underline;'
        >
          Bekijk de originele vacature
        </a>
      </div>
    `
    : '';

  return `
    <div style='
      font-family:Arial, Helvetica, sans-serif;
      font-size:14px;
      line-height:1.45;
      color:#222222;
      max-width:900px;
    '>

      <div style='font-weight:bold; margin-bottom:12px;'>
        VACATURE
      </div>

      ${row('Functie', d.vacatureTitel)}
      ${row('Broker', d.broker)}
      ${row('Referentienummer', d.referentienummer)}
      ${row('Categorie', d.categorie)}

      ${matchSection}

      ${vacancySection}

      ${keywordsSection}

      ${assessmentSection}

      ${urlSection}

    </div>
  `;
})() }}

parameters.jsCode:
const httpItems = $input.all();
const urlItems = $('Code-Exctract URL').all();

/**
 * Decodeert de meest voorkomende HTML-entiteiten,
 * inclusief numerieke entiteiten.
 */
function decodeHtml(value = '') {
  return String(value)
    .replace(/&#(\d+);/g, (_, code) =>
      String.fromCodePoint(Number(code))
    )
    .replace(/&#x([0-9a-f]+);/gi, (_, code) =>
      String.fromCodePoint(parseInt(code, 16))
    )
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&apos;/gi, "'")
    .replace(/&#39;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>');
}

/**
 * Zet HTML om naar leesbare platte tekst.
 */
function htmlNaarTekst(html = '') {
  return decodeHtml(
    String(html)
      .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, ' ')
      .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, ' ')
      .replace(/<noscript\b[^>]*>[\s\S]*?<\/noscript>/gi, ' ')
      .replace(/<svg\b[^>]*>[\s\S]*?<\/svg>/gi, ' ')
      .replace(/<!--[\s\S]*?-->/g, ' ')
      .replace(/<(br|hr)\s*\/?>/gi, '\n')
      .replace(
        /<\/(p|div|section|article|li|h1|h2|h3|h4|h5|h6|tr)>/gi,
        '\n'
      )
      .replace(/<li\b[^>]*>/gi, '• ')
      .replace(/<[^>]+>/g, ' ')
  )
    .replace(/\r/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

/**
 * Haalt de inhoud van een meta-tag op.
 */
function haalMetaContent(html, naam) {
  const escapedNaam = naam.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  const patronen = [
    new RegExp(
      `<meta[^>]+(?:name|property)=["']${escapedNaam}["'][^>]+content=["']([^"']*)["'][^>]*>`,
      'i'
    ),
    new RegExp(
      `<meta[^>]+content=["']([^"']*)["'][^>]+(?:name|property)=["']${escapedNaam}["'][^>]*>`,
      'i'
    )
  ];

  for (const patroon of patronen) {
    const match = String(html).match(patroon);

    if (match?.[1]) {
      return decodeHtml(match[1]).trim();
    }
  }

  return '';
}

/**
 * Haalt de vacaturetitel uit de HTML.
 */
function haalTitel(html) {
  const ogTitel = haalMetaContent(html, 'og:title');

  if (ogTitel) {
    return ogTitel
      .replace(/\s*-\s*LibLab\s*-\s*Libertas Labor\s*$/i, '')
      .replace(/\s*-\s*LibLab\s*$/i, '')
      .trim();
  }

  const titleMatch = String(html).match(
    /<title[^>]*>([\s\S]*?)<\/title>/i
  );

  if (titleMatch?.[1]) {
    return decodeHtml(titleMatch[1])
      .replace(/\s*-\s*LibLab\s*-\s*Libertas Labor\s*$/i, '')
      .replace(/\s*-\s*LibLab\s*$/i, '')
      .trim();
  }

  const h1Match = String(html).match(
    /<h1[^>]*>([\s\S]*?)<\/h1>/i
  );

  if (h1Match?.[1]) {
    return htmlNaarTekst(h1Match[1]);
  }

  return '';
}

/**
 * Probeert alleen het inhoudelijke vacaturegedeelte te pakken.
 * Valt terug op de volledige pagina wanneer het blok niet wordt gevonden.
 */
function haalVacatureTekst(html) {
  const patronen = [
    /<div[^>]+class=["'][^"']*awsm-job-content[^"']*["'][^>]*>([\s\S]*?)<div[^>]+class=["'][^"']*awsm-job-form/gi,
    /<div[^>]+class=["'][^"']*awsm-job-content[^"']*["'][^>]*>([\s\S]*?)<\/div>\s*<\/div>/gi,
    /<article[^>]*>([\s\S]*?)<\/article>/gi,
    /<main[^>]*>([\s\S]*?)<\/main>/gi
  ];

  for (const patroon of patronen) {
    const match = patroon.exec(String(html));

    if (match?.[1]) {
      const tekst = htmlNaarTekst(match[1]);

      if (tekst.length >= 100) {
        return tekst;
      }
    }
  }

  return htmlNaarTekst(html);
}

/**
 * Sommige LibLab-pagina's beginnen de meta description met:
 * "Kadaster Kadaster registreert..."
 *
 * Deze functie herkent zo'n herhaalde naam.
 */
function haalHerhaaldeNaamUitBeschrijving(beschrijving) {
  const woorden = String(beschrijving)
    .replace(/[|•]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .split(' ')
    .filter(Boolean);

  const maximaalAantalWoorden = Math.min(
    6,
    Math.floor(woorden.length / 2)
  );

  for (let aantal = maximaalAantalWoorden; aantal >= 1; aantal--) {
    const eersteDeel = woorden.slice(0, aantal).join(' ');
    const tweedeDeel = woorden.slice(aantal, aantal * 2).join(' ');

    const normaliseer = waarde =>
      waarde
        .toLowerCase()
        .replace(/[.,;:!?()[\]{}"'’]/g, '')
        .trim();

    if (
      normaliseer(eersteDeel) &&
      normaliseer(eersteDeel) === normaliseer(tweedeDeel)
    ) {
      return eersteDeel
        .replace(/[.,;:!?]+$/g, '')
        .trim();
    }
  }

  return '';
}

/**
 * Extra fallback: opdrachtgever uit een JSON-LD afbeeldingscaption.
 * Bijvoorbeeld: "Het Kadaster".
 */
function haalCaptionUitJsonLd(html) {
  const matches = String(html).matchAll(
    /"caption"\s*:\s*"([^"]+)"/gi
  );

  for (const match of matches) {
    const caption = decodeHtml(
      match[1]
        .replace(/\\\//g, '/')
        .replace(/\\"/g, '"')
    ).trim();

    if (
      caption &&
      !/liblab|logo|avatar|profielfoto/i.test(caption)
    ) {
      return caption;
    }
  }

  return '';
}

/**
 * Probeert opdrachtgever uit de vacaturepagina af te leiden.
 */
function haalOpdrachtgever(html, vacatureTekst) {
  const description =
    haalMetaContent(html, 'description') ||
    haalMetaContent(html, 'og:description') ||
    haalMetaContent(html, 'twitter:description');

  const herhaaldeNaam =
    haalHerhaaldeNaamUitBeschrijving(description);

  if (herhaaldeNaam) {
    return herhaaldeNaam;
  }

  const caption = haalCaptionUitJsonLd(html);

  if (caption) {
    return caption;
  }

  const tekstPatronen = [
    /(?:opdrachtgever|organisatie|klant)\s*[:\-]\s*([^\n|]{2,100})/i,
    /(?:werken bij|voor)\s+([A-ZÀ-Ý][^\n,.]{2,80})/i
  ];

  for (const patroon of tekstPatronen) {
    const match = String(vacatureTekst).match(patroon);

    if (match?.[1]) {
      return match[1]
        .replace(/\s+/g, ' ')
        .replace(/[.;,:]+$/g, '')
        .trim();
    }
  }

  return '';
}

return httpItems.map((item, index) => {
  const httpData = item.json ?? {};
  const urlData = urlItems[index]?.json ?? {};

  const ruweHtml =
    typeof httpData.data === 'string'
      ? httpData.data
      : typeof httpData.body === 'string'
        ? httpData.body
        : typeof httpData.content === 'string'
          ? httpData.content
          : '';

  const vacatureTitel =
    httpData.vacatureTitel ||
    httpData.titel ||
    httpData.title ||
    urlData.vacatureTitel ||
    urlData.titel ||
    urlData.title ||
    haalTitel(ruweHtml);

  const vacatureTekst =
    httpData.vacatureTekst ||
    httpData.tekst ||
    httpData.text ||
    haalVacatureTekst(ruweHtml);

  const vacatureUrl =
    urlData.vacatureUrl ||
    urlData.url ||
    httpData.vacatureUrl ||
    httpData.url ||
    '';

  const broker =
    urlData.broker ||
    httpData.broker ||
    urlData.brokerNaam ||
    httpData.brokerNaam ||
    '';

  const opdrachtgever =
    urlData.opdrachtgever ||
    httpData.opdrachtgever ||
    urlData.klant ||
    httpData.klant ||
    urlData.klantNaam ||
    httpData.klantNaam ||
    haalOpdrachtgever(ruweHtml, vacatureTekst);

  const brokerEmail =
    urlData.brokerEmail ||
    httpData.brokerEmail ||
    '';

  const emailOntvangenOp =
    urlData.emailOntvangenOp ||
    httpData.emailOntvangenOp ||
    '';

  const bronBerichtId =
    urlData.bronBerichtId ||
    httpData.bronBerichtId ||
    '';

  const bronBerichtOnderwerp =
    urlData.bronBerichtOnderwerp ||
    httpData.bronBerichtOnderwerp ||
    '';

  return {
    json: {
      vacatureTitel,
      vacatureTekst,
      vacatureUrl,
      broker,
      brokerEmail,
      opdrachtgever,
      emailOntvangenOp,
      bronBerichtId,
      bronBerichtOnderwerp,
      bronHtml: ruweHtml
    },
    pairedItem: {
      item: index
    }
  };
});

const result = [];
const gevondenUrls = new Set();

const inputItems = $input.all();

for (let inputIndex = 0; inputIndex < inputItems.length; inputIndex++) {
  const item = inputItems[inputIndex];

  const body =
    item.json.body?.content ||
    item.json.body ||
    item.json.text ||
    item.json.content ||
    '';

  const text =
    typeof body === 'string'
      ? body
      : JSON.stringify(body);

  const bronBerichtId =
    item.json.id ||
    '';

  const bronBerichtOnderwerp =
    item.json.subject ||
    '';

  const brokerNaam =
    item.json.from?.emailAddress?.name ||
    item.json.sender?.emailAddress?.name ||
    '';

  const brokerEmail =
    item.json.from?.emailAddress?.address ||
    item.json.sender?.emailAddress?.address ||
    '';

  const emailOntvangenOp =
    item.json.receivedDateTime ||
    item.json.createdDateTime ||
    '';

  const matches =
    text.match(
      /https?:\/\/(?:www\.)?liblab\.nl\/opdrachten\/[^\s"'<>]+/gi
    ) || [];

  for (const match of matches) {
    const vacatureUrl = match
      .replace(/&amp;/gi, '&')
      .replace(/[),.;]+$/g, '')
      .trim();

    if (!vacatureUrl || gevondenUrls.has(vacatureUrl)) {
      continue;
    }

    gevondenUrls.add(vacatureUrl);

    result.push({
      json: {
        vacatureUrl,
        broker: brokerNaam,
        brokerEmail,
        emailOntvangenOp,
        bronBerichtId,
        bronBerichtOnderwerp
      },
      pairedItem: {
        item: inputIndex
      }
    });
  }
}

// Gebruik uitsluitend de centrale configuratie voor de verwerkingslimiet.
let limiet = result.length;
try {
  const cfg = $('Code-Configuratie').first().json;
  if (cfg?.testmodus && Number(cfg.maximaalAantalVacatures) > 0) {
    limiet = Number(cfg.maximaalAantalVacatures);
  }
} catch (e) {}
return result.slice(0, limiet);

const inputItems = $input.all();
const output = [];

for (let i = 0; i < inputItems.length; i++) {
  const item = inputItems[i];
  const input = item.json;

  // Ruwe waarde uit de LLM-node halen.
  const rawValue =
    input.output ??
    input.text ??
    input.content ??
    input.response ??
    input.body ??
    input;

  let parsed;

  if (rawValue !== null && typeof rawValue === 'object') {
    parsed = rawValue;
  } else {
    if (typeof rawValue !== 'string' || rawValue.trim() === '') {
      throw new Error(
        `Geen geldige JSON-tekst ontvangen. Beschikbare velden: ${Object.keys(input).join(', ')}`
      );
    }

    let cleaned = rawValue
      .trim()
      .replace(/^```(?:json)?\s*/i, '')
      .replace(/\s*```$/, '')
      .trim();

    try {
      parsed = JSON.parse(cleaned);
    } catch (error) {
      throw new Error(
        `Ongeldige JSON ontvangen: ${error.message}. Begin van de invoer: ${cleaned.slice(0, 300)}`
      );
    }
  }

  // Bijbehorende vacaturegegevens ophalen uit de juiste bronnode via de
  // paired-item-relatie. Beide takken (LibLab en Circle8) komen samen in
  // dezelfde LLM-node, dus koppelen op index i is onbetrouwbaar: itemMatching
  // volgt de paired-item-keten terug naar de echte bron van dit item.
  let bron = {};

  const heeftVacatureData = (obj) =>
    obj && (obj.vacatureTitel || obj.vacatureUrl || obj.vacatureTekst);

  // 1) Probeer de bron te vinden via de paired-item-keten (betrouwbaar).
  try {
    const m = $('Code-Titel + Tekst + URL').itemMatching(i);
    if (heeftVacatureData(m?.json)) {
      bron = m.json;
    }
  } catch (e) {}

  if (!heeftVacatureData(bron)) {
    try {
      const m = $('Code-Circle8 e-mail naar vacature').itemMatching(i);
      if (heeftVacatureData(m?.json)) {
        bron = m.json;
      }
    } catch (e) {}
  }

  if (!heeftVacatureData(bron)) {
    try {
      const m = $('Code-DPP detail').itemMatching(i);
      if (heeftVacatureData(m?.json)) {
        bron = m.json;
      }
    } catch (e) {}
  }

  // 2) Fallback op index i, mocht paired-item niet beschikbaar zijn.
  if (!heeftVacatureData(bron)) {
    try {
      const bronItems = $('Code-Titel + Tekst + URL').all();
      if (heeftVacatureData(bronItems[i]?.json)) {
        bron = bronItems[i].json;
      }
    } catch (e) {}
  }

  if (!heeftVacatureData(bron)) {
    try {
      const bronItems = $('Code-Circle8 e-mail naar vacature').all();
      if (heeftVacatureData(bronItems[i]?.json)) {
        bron = bronItems[i].json;
      }
    } catch (e) {}
  }

  if (!heeftVacatureData(bron)) {
    try {
      const bronItems = $('Code-DPP detail').all();
      if (heeftVacatureData(bronItems[i]?.json)) {
        bron = bronItems[i].json;
      }
    } catch (e) {}
  }

  const vacatureHtml = parsed.vacatureHtml ?? '';
  const medewerkers = Array.isArray(parsed.medewerkers) ? parsed.medewerkers : [];

  // Eén output-item per medewerker, met platgeslagen velden.
  for (const medewerker of medewerkers) {
    output.push({
      json: {
        medewerker: medewerker.naam ?? '',
        score: Number(medewerker.score ?? 0),
        gevondenKeywords: Array.isArray(medewerker.gevondenKeywords)
          ? medewerker.gevondenKeywords
          : [],
        reden: medewerker.reden ?? '',

        vacatureHtml,
        vacatureTitel: bron.vacatureTitel ?? '',
        vacatureUrl: bron.vacatureUrl ?? '',
        vacatureTekst: bron.vacatureTekst ?? '',
        broker: bron.broker ?? '',
        brokerEmail: bron.brokerEmail ?? '',
        opdrachtgever: bron.opdrachtgever ?? '',
        bronBerichtId: bron.bronBerichtId ?? '',
        bronBerichtOnderwerp: bron.bronBerichtOnderwerp ?? '',
        emailOntvangenOp: bron.emailOntvangenOp ?? '',
        deduplicatieSleutel: bron.deduplicatieSleutel ?? '',
      },
      pairedItem: { item: i },
    });
  }
}

return output;

// Versie 1.4.2
// De archivering gebruikt uitsluitend oorspronkelijke Outlook message ID's
// uit Code-Bron herkennen. Verwerkte vacature-items bepalen alleen welke
// bronberichten mogen worden gearchiveerd.

let origineleEmails = [];
let verwerkteVacatures = [];

try {
  origineleEmails = $('Code-Bron herkennen').all();
} catch (e) {}

try {
  verwerkteVacatures = $('Code-JSON.parse').all();
} catch (e) {}

if (origineleEmails.length === 0 || verwerkteVacatures.length === 0) {
  return [];
}

const normaliseer = (waarde) => String(waarde ?? '').trim().toLowerCase();

const verwerkteIds = new Set();
const verwerkteOnderwerpen = new Set();
const verwerkteBrokerEmails = new Set();
const verwerkteBronCodes = new Set();

for (const item of verwerkteVacatures) {
  const j = item.json || {};

  const id = String(j.bronBerichtId ?? '').trim();
  const onderwerp = normaliseer(j.bronBerichtOnderwerp);
  const brokerEmail = normaliseer(j.brokerEmail);
  const broker = normaliseer(j.broker);

  if (id) verwerkteIds.add(id);
  if (onderwerp) verwerkteOnderwerpen.add(onderwerp);
  if (brokerEmail) verwerkteBrokerEmails.add(brokerEmail);

  if (broker.includes('liblab')) verwerkteBronCodes.add('liblab');
  if (broker.includes('circle8')) verwerkteBronCodes.add('circle8');
  if (broker.includes('publieke partner')) {
    verwerkteBronCodes.add('depubliekepartner');
  }
}

const uniekeEmails = new Map();

for (const item of origineleEmails) {
  const j = item.json || {};

  const origineelMessageId = String(j.id ?? '').trim();
  if (!origineelMessageId) continue;

  const onderwerp = normaliseer(j.subject ?? j.bronBerichtOnderwerp);
  const brokerEmail = normaliseer(j.brokerEmail);
  const bronCode = normaliseer(j.bronCode);

  const exactIdGevonden = verwerkteIds.has(origineelMessageId);
  const onderwerpGevonden =
    Boolean(onderwerp) && verwerkteOnderwerpen.has(onderwerp);
  const brokerEmailGevonden =
    Boolean(brokerEmail) && verwerkteBrokerEmails.has(brokerEmail);
  const bronGevonden =
    Boolean(bronCode) && verwerkteBronCodes.has(bronCode);

  const moetArchiveren =
    exactIdGevonden ||
    onderwerpGevonden ||
    (brokerEmailGevonden && bronGevonden);

  if (!moetArchiveren) continue;

  if (!uniekeEmails.has(origineelMessageId)) {
    uniekeEmails.set(origineelMessageId, {
      json: {
        bronBerichtId: origineelMessageId,
