    throw new Error(`Vacaturevalidatie mislukt voor item ${index + 1}: ${fouten.join('; ')}. Titel: ${String(j.vacatureTitel ?? '').slice(0,120)}`);
  }
  output.push({ json: { ...j, validatieStatus: 'geldig' }, pairedItem: item.pairedItem });
}
return output;

const verplaatste = $input.all();
let verwerkt = [];
let emails = [];
let voorDeduplicatie = [];
let geldigeVacatures = [];

try { verwerkt = $('Code-JSON.parse').all(); } catch (e) {}
try { emails = $('Get many messages').all(); } catch (e) {}
try { geldigeVacatures = $('Code-Validatie vacature').all(); } catch (e) {}

for (const nodeNaam of [
  'Code-Titel + Tekst + URL',
  'Code-Circle8 e-mail naar vacature',
  'Code-DPP detail'
]) {
  try { voorDeduplicatie.push(...$(nodeNaam).all()); } catch (e) {}
}

const cfg = $('Code-Configuratie').first().json;
const store = $getWorkflowStaticData('global');
store.verwerkteVacatures ??= {};
const nu = Date.now();

for (const item of verwerkt) {
  const sleutel = String(item.json?.deduplicatieSleutel ?? '').trim();
  if (sleutel && !cfg.testmodus) store.verwerkteVacatures[sleutel] = nu;
}

const maxSleutels = Number(cfg.maximaalAantalDeduplicatieSleutels || 5000);
store.verwerkteVacatures = Object.fromEntries(
  Object.entries(store.verwerkteVacatures)
    .sort((a,b) => Number(b[1]) - Number(a[1]))
    .slice(0, maxSleutels)
);

function uniekeSleutels(items) {
  return new Set(items.map(item => {
    const j = item.json || {};
    return String(
      j.deduplicatieSleutel ||
      j.vacatureUrl ||
      `${j.broker || ''}|${j.vacatureTitel || ''}|${String(j.vacatureTekst || '').slice(0,100)}`
    );
  }).filter(Boolean));
}

const vacaturesVoor = uniekeSleutels(voorDeduplicatie);
const vacaturesNa = uniekeSleutels(geldigeVacatures);
const succesvolleArchivering = verplaatste.filter(
  item => String(item.json?.archiveStatus || 'succes') === 'succes'
);
const mislukteArchivering = verplaatste.filter(
  item => String(item.json?.archiveStatus || '') === 'mislukt'
);
const bronberichten = new Set(
  succesvolleArchivering.map(item => String(
    item.json?.id ||
    item.json?.origineelOutlookMessageId ||
    item.json?.bronBerichtId ||
    ''
  )).filter(Boolean)
);

const matchesBovenDrempel = verwerkt.filter(
  item => Number(item.json?.score || 0) >= Number(cfg.minimumScore || 0)
);

const brokers = {};
for (const item of geldigeVacatures) {
  const broker = String(item.json?.broker || 'Onbekend');
  brokers[broker] = (brokers[broker] || 0) + 1;
}

const logRecord = {
  uitvoering_id: String($execution?.id || ''),
  uitgevoerd_op: new Date().toISOString(),
  workflow_naam: cfg.workflowNaam || 'Taxonic vacatureselectie',
  workflow_versie: cfg.workflowVersie || '1.3.2',
  prompt_versie: cfg.promptVersie || '1.3.2',
  status: 'succes',
  testmodus: Boolean(cfg.testmodus),
  aantal_emails_gelezen: emails.length,
  aantal_vacatures_voor_deduplicatie: vacaturesVoor.size,
  aantal_vacatures: vacaturesNa.size,
  aantal_dubbele_overgeslagen: Math.max(0, vacaturesVoor.size - vacaturesNa.size),
  aantal_matchregels_totaal: verwerkt.length,
  aantal_matches: matchesBovenDrempel.length,
  aantal_gearchiveerde_emails: bronberichten.size,
  aantal_archivering_mislukt: mislukteArchivering.length,
  archivering_fouten: JSON.stringify(
    mislukteArchivering.map(item => ({
      onderwerp: item.json?.bronBerichtOnderwerp || '',
      messageId: item.json?.origineelOutlookMessageId || item.json?.bronBerichtId || '',
      fout: item.json?.archiveFout || ''
    }))
  ).slice(0,10000),
  deduplicatie_opgeslagen: cfg.testmodus ? 0 : vacaturesNa.size,
  brokers: JSON.stringify(brokers),
  match_samenvatting: JSON.stringify(matchesBovenDrempel.map(item => ({
    medewerker: item.json?.medewerker || '',
    score: Number(item.json?.score || 0),
    vacatureTitel: item.json?.vacatureTitel || '',
    broker: item.json?.broker || ''
  }))).slice(0,10000)
};

return [{ json: { logRecord } }];

let log = {};
try { log = $('Log-Uitvoering').first().json.logRecord || {}; } catch (e) {}
return [{ json: { ...log, databaseLogging: 'afgerond' } }];

const r = $input.first().json || {};

const emails = Number(r.aantal_emails_gelezen || 0);
const vacaturesVoor = Number(r.aantal_vacatures_voor_deduplicatie || 0);
const vacatures = Number(r.aantal_vacatures || 0);
const matches = Number(r.aantal_matches || 0);
const matchregels = Number(r.aantal_matchregels_totaal || 0);
const gearchiveerd = Number(r.aantal_gearchiveerde_emails || 0);
const dubbelen = Number(r.aantal_dubbele_overgeslagen || 0);

const waarschuwingen = [];

if (emails > 0 && vacaturesVoor === 0) {
  waarschuwingen.push('E-mails gelezen, maar geen vacatures uit bronnen gehaald.');
}
if (vacaturesVoor > 0 && vacatures === 0) {
  waarschuwingen.push('Vacatures gevonden, maar geen vacatures door validatie gekomen.');
}
if (vacatures > 0 && matchregels === 0) {
  waarschuwingen.push('Geldige vacatures gevonden, maar geen AI-matchregels geproduceerd.');
}
if (!r.testmodus && vacatures > 0 && gearchiveerd === 0) {
  waarschuwingen.push('Vacatures verwerkt, maar geen bronberichten gearchiveerd.');
}
if (dubbelen > vacaturesVoor) {
  waarschuwingen.push('Deduplicatie-aantallen lijken inconsistent.');
}

let gezondheidsstatus = 'groen';
if (waarschuwingen.length > 0) gezondheidsstatus = 'oranje';
if (
  (emails > 0 && vacaturesVoor === 0) ||
  (vacatures > 0 && matchregels === 0)
) {
  gezondheidsstatus = 'rood';
}

const conversieVacature = emails > 0
  ? Math.round((vacatures / emails) * 10000) / 100
  : 0;

const conversieMatch = vacatures > 0
  ? Math.round((matches / vacatures) * 10000) / 100
  : 0;

return [{
  json: {
    ...r,
    monitoring: {
      gemeten_op: new Date().toISOString(),
      gezondheidsstatus,
      aantal_waarschuwingen: waarschuwingen.length,
      waarschuwingen,
      conversie_email_naar_vacature_pct: conversieVacature,
      matches_per_vacature_pct: conversieMatch,
      workflow_stabiele_basis: '1.3.2',
      monitoring_versie: '1.4.2'
    }
  }
}];

// Laat alleen bruikbare DPP-vacatures door.
// Een kapotte detailpagina stopt niet langer de volledige workflow.

const geldig = [];
const overgeslagen = [];

for (const item of $input.all()) {
  const j = item.json || {};
  const titel = String(j.vacatureTitel || '').trim();
  const tekst = String(j.vacatureTekst || '').trim();

  if (
    j.dppDetailStatus === 'verwerkt' &&
    titel &&
    tekst.length >= 100
  ) {
    geldig.push(item);
  } else {
    overgeslagen.push({
      url: j.vacatureUrl || '',
      titel,
      fout: j.dppDetailFout || 'Onvolledige DPP-vacature'
    });
  }
}

const state = $getWorkflowStaticData('global');
state.laatsteDppResultaat = {
  gemetenOp: new Date().toISOString(),
  ontvangen: $input.all().length,
  geldig: geldig.length,
  overgeslagen: overgeslagen.length,
  fouten: overgeslagen.slice(0, 25)
};

return geldig;

// Normaliseer succesvolle en mislukte Outlook-verplaatsingen.
// Een archiveringsfout stopt de workflow niet.

return $input.all().map((item) => {
  const j = item.json || {};

  const fout =
    j.error?.message ||
    j.error ||
    j.message ||
    j.errorDescription ||
    '';

  const heeftFout = Boolean(String(fout || '').trim());

  return {
    json: {
      ...j,
      archiveStatus: heeftFout ? 'mislukt' : 'succes',
      archiveFout: heeftFout ? String(fout) : '',
      archiveTijdstip: new Date().toISOString(),
      archive404:
        heeftFout &&
        (
          String(fout).includes('404') ||
          String(fout).toLowerCase().includes('not found')
        )
    }
  };
});
